-- Constrain new uploads while retaining training videos and project documents.
update storage.buckets set allowed_mime_types=array['audio/webm','audio/ogg','audio/mpeg','audio/mp3','audio/mp4','audio/x-m4a','audio/wav','audio/wave','audio/x-wav','audio/vnd.wave','audio/flac','audio/x-flac','audio/aac','audio/opus','audio/3gpp'], file_size_limit=52428800 where id='recordings';
update storage.buckets set allowed_mime_types=array['audio/webm','audio/ogg','audio/mpeg','audio/mp3','audio/mp4','audio/x-m4a','audio/wav','audio/wave','audio/x-wav','audio/vnd.wave','audio/flac','audio/x-flac','audio/aac','audio/opus','audio/3gpp','video/mp4','video/webm','video/quicktime','video/ogg','image/jpeg','image/png','image/webp','image/gif','text/plain','text/markdown','text/csv','text/vtt','application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.openxmlformats-officedocument.presentationml.presentation'] where id='adatacore-project-library';